'use strict';
const steps=[
 {label:'01 / RESEARCH',title:'先有依据，再有好内容。',description:'按最多收藏、最多点赞两种排序检索，合并去重并核验数据。从相关候选中选出 3 条参考，记录原始链接与采集时间。',foot:'没有合格数据，就说明缺口，不编造结果。',rows:[['搜索与去重','双排序'],['点赞 / 收藏','≥ 1000 / ≥ 300'],['合格参考','3 条真实笔记']]},
 {label:'02 / STYLE',title:'把审美的决定权，交给你。',description:'完整展示 10 种风格，并结合主题推荐 1–2 种。回复风格编号、名称，或确认推荐后，才开始生成图片。',foot:'已明确指定风格时直接采用。人物构图也可调整为无人物版本。',rows:[['视觉方向','10 种可选'],['创作者确认','编号 / 名称 / 用推荐'],['图片生成','确认后开始']]},
 {label:'03 / DRAFT',title:'不止一个标题，是完整的表达。',description:'根据参考与差异化方向，写出标题、正文和话题标签。让每一页都服务于具体信息，减少重复表达与空泛的口号。',foot:'文案可在等待风格确认时交付；不编造个人经历、产品效果或数据。',rows:[['标题备选','3 个'],['正文篇幅','约 300–600 字'],['相关标签','5–8 个']]},
 {label:'04 / DELIVER',title:'从屏幕上的想法，到可用的作品。',description:'默认先生成一张独立封面，核验实际像素与文字可读性。需要内容页时，延续已确认的视觉语言，逐张制作、独立交付。',foot:'目标画幅 3:4（推荐 1080×1440）；实际产出需要图片生成工具。',rows:[['默认交付','1 张独立封面'],['内容页','按需追加，默认 5 张'],['质量检查','像素 / 文字 / 一致性']]}
];
const stepButtons=[...document.querySelectorAll('[data-step]')];
function selectStep(index){const s=steps[index];stepButtons.forEach((b,i)=>{b.classList.toggle('active',i===index);b.setAttribute('aria-selected',String(i===index));});document.querySelector('#step-panel').setAttribute('aria-labelledby','step-tab-'+index);document.querySelector('#step-kicker').textContent=s.label;document.querySelector('#step-title').textContent=s.title;document.querySelector('#step-description').textContent=s.description;document.querySelector('#step-foot').textContent=s.foot;const output=document.querySelector('#step-output');output.replaceChildren();s.rows.forEach(([a,b],i)=>{const line=document.createElement('div');line.className='output-line';const label=document.createElement('span');label.textContent=a;const value=document.createElement('b');value.textContent=b;if(i===2)value.className='green';line.append(label,value);output.append(line);});}
stepButtons.forEach((b,i)=>b.addEventListener('click',()=>selectStep(i)));
const styles=[['深色渐变风','linear-gradient(140deg,#3b5993,#8c65a8)','深色渐变与高对比大字，让主题更有冲击力。适合科技、AI 和强观点选题。'],['纯色扁平风','#d9fa79','清晰的纯色块和扁平图形，让信息轻松被看见。适合干货清单与清爽科普。'],['产品主视觉风','#bfc7d4','让产品或界面成为主角，文字负责引导。没有真实素材时使用明确的示意图。'],['对比卡片风','#d6886b','将两组信息并置，突出差异。适合前后对比、避坑清单和方案选择。'],['极简留白风','#e6e3d5','让文字成为主角。大面积留白与克制的装饰，适合金句、品牌感和少字封面。'],['海报拼贴风','#e69a7c','用卡片、纸张与贴纸构建层次。适合素材丰富、信息层次多的主题。'],['人物侧置留白风','#bca794','主体靠一侧，另一侧留给标题。这里用无人物插画示意，保留相同留白逻辑。'],['背影构图风','#61755c','由主体引导视线，标题在留白处展开。这里展示无人物空间版本，适合旅程与启发。'],['局部出镜风','#c9956c','放大一个细节，让步骤或产品成为焦点。预览用卧室局部示意，适合具体方法。'],['正面对视风','#dfc4a4','强调正面主体与信任感。这里使用无人物居中版本，实际人物素材需另行提供。']];
const styleGrid=document.querySelector('#style-buttons');styles.forEach(([name,color],i)=>{const b=document.createElement('button');b.className='style-button';b.setAttribute('aria-pressed',String(i===4));b.setAttribute('aria-label',(i+1)+' '+name);const num=document.createElement('span');num.className='style-number';num.textContent=String(i+1).padStart(2,'0');const text=document.createElement('span');text.textContent=name;const swatch=document.createElement('span');swatch.className='swatch';swatch.style.background=color;b.append(num,text,swatch);b.addEventListener('click',()=>{styleGrid.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed','false'));b.setAttribute('aria-pressed','true');document.querySelector('#style-name').textContent=String(i+1).padStart(2,'0')+' / '+name;document.querySelector('#style-description').textContent=styles[i][2];document.querySelector('#style-cover').className='style-cover style-'+(i+1);});styleGrid.append(b);});
const commands=[{code:'python3 scripts/install_skill.py --project /你的项目路径',caption:'解压源码包，在项目根目录运行',hint:'将「/你的项目路径」替换为实际项目文件夹。'},{code:'使用本项目的 $xiaohongshu-content，主题是「租房卧室改造」。',caption:'在已安装技能的 Codex 项目中发送',hint:'先取得真实参考，再选择你喜欢的视觉风格。'},{code:'沿用刚才确认的封面风格，再生成 5 张内容页，每张独立交付。',caption:'封面完成后，继续在同一会话中发送',hint:'内容页按需生成，默认不会一次生成整套。'}];
const commandButtons=[...document.querySelectorAll('[data-command]')];commandButtons.forEach((b,i)=>b.addEventListener('click',()=>{commandButtons.forEach((x,j)=>{x.classList.toggle('active',i===j);x.setAttribute('aria-selected',String(i===j));});document.querySelector('#command-panel').setAttribute('aria-labelledby','command-tab-'+i);document.querySelector('#install-code').textContent=commands[i].code;document.querySelector('#command-caption').textContent=commands[i].caption;document.querySelector('#command-hint').textContent='↳ '+commands[i].hint;}));
document.querySelectorAll('[role=tablist]').forEach(list=>list.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const tabs=[...list.querySelectorAll('[role=tab]')];let index=tabs.indexOf(document.activeElement);if(index<0)return;e.preventDefault();index=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[index].focus();tabs[index].click();}));
let toastTimer;function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2800);}
async function copyText(text){if(navigator.clipboard&&window.isSecureContext){try{await navigator.clipboard.writeText(text);return true;}catch{}}const field=document.createElement('textarea');field.value=text;field.style.cssText='position:fixed;left:-9999px;top:0';document.body.append(field);field.select();let copied=false;try{copied=document.execCommand('copy');}catch{}field.remove();return copied;}
document.querySelectorAll('[data-copy-target]').forEach(b=>b.addEventListener('click',async()=>{const text=document.getElementById(b.dataset.copyTarget).textContent;const ok=await copyText(text);toast(ok?'已复制，可粘贴到你的项目中':'复制未成功，请选中命令手动复制');}));
const menu=document.querySelector('.menu-button');const nav=document.querySelector('.nav nav');menu.addEventListener('click',()=>{const opened=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(opened));menu.setAttribute('aria-label',opened?'关闭菜单':'打开菜单');});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','打开菜单');}));
